    internal sealed class DiscoveryDesignRecord
    {
        public string Id { get; set; }
        public string ProtocolId { get; set; }
        public string CreatedUtc { get; set; }
        public string ProtocolFingerprint { get; set; }
        public string PreregistrationFingerprint { get; set; }
        public string DesignFingerprint { get; set; }
        public string CertificateHash { get; set; }
        public string Method { get; set; }
        public List<DiscoveryRun> Runs { get; set; }
        public DiscoveryDesignDiagnostics Diagnostics { get; set; }
        public DiscoveryDiscrimination Discrimination { get; set; }
        public List<DiscoveryPowerPlan> PowerPlans { get; set; }
        public DiscoveryDesignRecord() { Runs = new List<DiscoveryRun>(); PowerPlans = new List<DiscoveryPowerPlan>(); }
        public override string ToString() { return (CreatedUtc ?? "") + "   ·   " + (Method ?? "DESIGN") + "   ·   " + Runs.Count.ToString(CultureInfo.InvariantCulture) + " runs   ·   " + (Diagnostics == null ? "UNDIAGNOSED" : (Diagnostics.Estimable ? "ESTIMABLE" : "RANK DEFICIENT")) + "   ·   cert " + ShortHash(CertificateHash); }
        private static string ShortHash(string value) { return String.IsNullOrWhiteSpace(value) ? "∅" : value.Substring(0, Math.Min(16, value.Length)); }
    }

