        public static void Open(Window owner, DeepSystemsContext ctx) { if (ctx == null) return; Load(ctx); OpenHub(owner, ctx, WorldKernel.ExternalIndex(ctx, false)); }

        public static void OpenFromWorldNode(Window owner, DeepSystemsContext ctx, WorldIndex index, string nodeId)
        {
            if (ctx == null || index == null || String.IsNullOrWhiteSpace(nodeId)) return; WorldNode node; if (!index.Nodes.TryGetValue(nodeId, out node)) { Open(owner, ctx); return; } Load(ctx); string fingerprint = HashText((node.Id ?? "") + "|" + (node.Kind ?? "") + "|" + (node.Label ?? "") + "|" + (node.Fingerprint ?? "")); OpenProjection(owner, ctx, index, "WORLD", node.Id, fingerprint, delegate { DiscoveryProtocol p = StarterProtocol("Measure · " + (node.Label ?? node.Kind), "A bounded observation protocol projected from a World Kernel passport. Identity and provenance remain evidence; they are not randomized causes."); p.EvidenceNodeIds.Add(node.Id); p.Factors[0].Name = "observable coordinate"; p.Factors[0].Controllable = false; p.Outcomes[0].Name = "measured signal"; p.Hypotheses[0].Statement = "The selected world object remains within its declared baseline envelope."; p.Hypotheses[1].Statement = "The selected world object exhibits a materially discriminable deviation."; return p; });
        }

        public static void OpenFromCivilResolution(Window owner, DeepSystemsContext ctx, WorldIndex index, CivilResolution resolution)
        {
            if (ctx == null || resolution == null) return; Load(ctx); WorldIndex target = index ?? WorldKernel.ExternalIndex(ctx, false); string fingerprint = HashText((resolution.Id ?? "") + "|" + (resolution.Title ?? "") + "|" + (resolution.Proposition ?? "") + "|" + (resolution.Status ?? "") + "|" + String.Join("|", (resolution.EvidenceNodeIds ?? new List<string>()).OrderBy(x => x).ToArray())); OpenProjection(owner, ctx, target, "CIVILIZATION", resolution.Id, fingerprint, delegate { DiscoveryProtocol p = StarterProtocol("Pilot · " + (resolution.Title ?? "Resolution"), "Preregistered policy-pilot scaffold projected from a civilization resolution. Adoption status is not evidence of efficacy."); p.EvidenceNodeIds.AddRange(resolution.EvidenceNodeIds ?? new List<string>()); p.Factors[0].Name = "pilot exposure"; p.Outcomes[0].Name = "preregistered resolution outcome"; p.Hypotheses[0].Statement = "The proposed resolution produces no practically relevant change under the declared pilot."; p.Hypotheses[1].Statement = resolution.Proposition ?? "The proposed resolution produces the declared practically relevant change."; return p; });
        }

        public static void OpenFromLogicTheory(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicTheory theory)
        {
            if (ctx == null || theory == null) return; Load(ctx); WorldIndex target = index ?? WorldKernel.ExternalIndex(ctx, false); Dictionary<string, string> truth = EpistemicLogicFoundry.ExternalTheoryTruth(ctx, theory); string fingerprint = HashText((theory.Id ?? "") + "|" + (theory.Name ?? "") + "|" + (theory.Status ?? "") + "|" + String.Join("|", truth.OrderBy(x => x.Key).Select(x => x.Key + "=" + x.Value).ToArray())); OpenProjection(owner, ctx, target, "LOGIC", theory.Id, fingerprint, delegate { DiscoveryProtocol p = StarterProtocol("Discriminate · " + (theory.Name ?? "Theory"), "Hypothesis-discrimination protocol projected from a frozen paraconsistent theory. Logical support and empirical likelihood remain separate coordinates."); p.Factors[0].Name = "evidence perturbation"; p.Factors[0].Controllable = false; p.Outcomes[0].Name = theory.Questions == null || theory.Questions.Count == 0 ? "theory discriminant" : theory.Questions[0]; p.Hypotheses[0].Statement = "The frozen theory's current proof spectrum remains observationally adequate."; p.Hypotheses[1].Statement = "A rival empirical mechanism explains the discriminant more accurately."; p.Assumptions.Add("Frozen truth spectrum at projection: " + String.Join(", ", truth.Select(x => x.Key + "=" + x.Value).Take(24).ToArray())); return p; });
        }

        public static void OpenFromVerificationModel(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model)
        {
            if (ctx == null || model == null) return; Load(ctx); WorldIndex target = index ?? WorldKernel.ExternalIndex(ctx, false); string fingerprint = VerificationKernel.Fingerprint(model); OpenProjection(owner, ctx, target, "VERIFICATION", model.Id, fingerprint, delegate { DiscoveryProtocol p = StarterProtocol("Conformance · " + (model.Name ?? "Finite-state model"), "Conformance measurement plan projected from a formal model. Empirical observation cannot replace the model-checking certificate, and the certificate cannot replace observation."); p.EvidenceNodeIds.AddRange(model.EvidenceNodeIds ?? new List<string>()); p.Factors[0].Name = "input / environment perturbation"; p.Outcomes[0].Name = "trace conformance indicator"; p.Outcomes[0].Scale = "BINARY"; p.Hypotheses[0].Statement = "Observed traces conform to the declared finite-state abstraction within the acceptance boundary."; p.Hypotheses[1].Statement = "Observed traces reveal a systematic abstraction or implementation fault."; p.Assumptions.Add(model.States.Count + " modeled states and " + model.Transitions.Count + " modeled transitions at projection."); return p; });
        }

        public static void OpenFromStrategyModel(Window owner, DeepSystemsContext ctx, WorldIndex index, StrategyModel model)
        {
            if (ctx == null || model == null) return; Load(ctx); WorldIndex target = index ?? WorldKernel.ExternalIndex(ctx, false); string fingerprint = CounterfactualStrategyKernel.Fingerprint(model); OpenProjection(owner, ctx, target, "STRATEGY", model.Id, fingerprint, delegate { DiscoveryProtocol p = ProjectStrategy(model); return p; });
        }

        private static void OpenProjection(Window owner, DeepSystemsContext ctx, WorldIndex index, string kind, string sourceId, string fingerprint, Func<DiscoveryProtocol> create)
        {
            DiscoveryProtocol existing = LatestProjection(kind, sourceId); if (existing != null && Eq(existing.SourceFingerprint, fingerprint)) { OpenProtocol(owner, ctx, index, existing); return; } if (existing != null) { string action = Choose(owner, "DISCOVERY PROJECTION DRIFT", "The source changed after an earlier experimental abstraction. Preserve the historical protocol boundary or create a current projection?", new[] { "OPEN HISTORICAL PROTOCOL", "CREATE CURRENT PROJECTION" }, "OPEN HISTORICAL PROTOCOL"); if (action == "OPEN HISTORICAL PROTOCOL") { OpenProtocol(owner, ctx, index, existing); return; } if (action != "CREATE CURRENT PROJECTION") return; }
            DiscoveryProtocol protocol = create(); protocol.SourceKind = kind; protocol.SourceId = sourceId; protocol.SourceFingerprint = fingerprint; Store.Protocols.Insert(0, protocol); TrimStore(); Save(ctx); AppendLedger(ctx, "PROJECTION_CREATED", protocol.Id, kind + " · " + sourceId, ExperimentalDesignKernel.ProtocolFingerprint(protocol), ""); OpenProtocol(owner, ctx, index, protocol);
        }

