        private static string CensusLine() { return Store.Protocols.Count(x => Active(x.Status)).ToString(CultureInfo.InvariantCulture) + " active protocols · " + Store.Protocols.Sum(x => x.Factors.Count).ToString(CultureInfo.InvariantCulture) + " factors · " + Store.Protocols.Sum(x => x.Outcomes.Count).ToString(CultureInfo.InvariantCulture) + " outcomes · " + Store.Protocols.Sum(x => x.Hypotheses.Count).ToString(CultureInfo.InvariantCulture) + " hypotheses · " + Store.Designs.Count.ToString(CultureInfo.InvariantCulture) + " frozen designs · " + Store.Observations.Count.ToString(CultureInfo.InvariantCulture) + " observations · " + Store.Preregistrations.Count.ToString(CultureInfo.InvariantCulture) + " preregistrations"; }

        private static void OpenProtocols(Window owner, DeepSystemsContext ctx, WorldIndex index) { Window w = W(owner, "YOMI · PROTOCOL CONSTELLATION", 1180, 780); DockPanel root = Shell("EXPERIMENTAL PROTOCOL CONSTELLATION", CensusLine()); WrapPanel tools = new WrapPanel(); tools.Children.Add(Btn("FORGE PROTOCOL", delegate { CreateProtocolPrompt(w, ctx, index); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox list = List(); list.ItemsSource = Store.Protocols.OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).ToList(); list.MouseDoubleClick += delegate { DiscoveryProtocol p = list.SelectedItem as DiscoveryProtocol; if (p != null) OpenProtocol(w, ctx, index, p); }; root.Children.Add(list); w.Content = root; w.Show(); }
        private static void CreateProtocolPrompt(Window owner, DeepSystemsContext ctx, WorldIndex index) { string name = Prompt(owner, "FORGE PROTOCOL", "Protocol name", "Discovery protocol " + DateTime.Now.ToString("yyyy-MM-dd HHmm", CultureInfo.InvariantCulture)); if (String.IsNullOrWhiteSpace(name)) return; string charter = PromptLarge(owner, "PROTOCOL CHARTER", "Question, scope, causal boundary and non-goals", "A bounded protocol for discriminating explicit hypotheses. Design synthesis is advisory and performs no experiment."); if (charter == null) return; DiscoveryProtocol p = StarterProtocol(name, charter); Store.Protocols.Insert(0, p); TrimStore(); Save(ctx); AppendLedger(ctx, "PROTOCOL_FORGED", p.Id, p.Name, ExperimentalDesignKernel.ProtocolFingerprint(p), ""); OpenProtocol(owner, ctx, index, p); }

        private static DiscoveryProtocol StarterProtocol(string name, string charter)
        {
            string now = Now(), factorId = Id("factor"), outcomeId = Id("outcome"); DiscoveryProtocol p = new DiscoveryProtocol { Id = Id("protocol"), Name = Short(name, 240), Charter = Short(charter, MaxLongText), Status = "DRAFT", CreatedUtc = now, UpdatedUtc = now, DesignMethod = "D_OPTIMAL", RequestedRuns = 16, CandidatePool = 256, Replicates = 1, Seed = 1337, Budget = 1000000, RiskCeiling = 1000000 };
            p.Factors.Add(new DiscoveryFactor { Id = factorId, Name = "experimental factor", Kind = "CONTINUOUS", Status = "ACTIVE", Minimum = -1, Maximum = 1, Levels = 2, Controllable = true, Unit = "coded" }); p.Outcomes.Add(new DiscoveryOutcome { Id = outcomeId, Name = "primary outcome", Scale = "CONTINUOUS", Direction = "TWO_SIDED", Status = "ACTIVE", Unit = "index", NoiseSigma = 1, RelevantEffect = 0.5, Alpha = 0.05, TargetPower = 0.8 });
            DiscoveryHypothesis nullH = new DiscoveryHypothesis { Id = Id("hypothesis"), Name = "H0 · baseline mechanism", Family = "NULL", Status = "ACTIVE", Statement = "The factor has no practically relevant effect on the primary outcome.", PriorWeight = 1, CreatedUtc = now, UpdatedUtc = now }; DiscoveryPrediction nullP = new DiscoveryPrediction { Id = Id("prediction"), OutcomeId = outcomeId, Intercept = 0, Sigma = 1, Distribution = "GAUSSIAN", Rationale = "Baseline response surface." }; nullP.Terms[factorId] = 0; nullH.Predictions.Add(nullP);
            DiscoveryHypothesis altH = new DiscoveryHypothesis { Id = Id("hypothesis"), Name = "H1 · alternative mechanism", Family = "ALTERNATIVE", Status = "ACTIVE", Statement = "The factor changes the primary outcome by the declared minimum relevant effect.", PriorWeight = 1, CreatedUtc = now, UpdatedUtc = now }; DiscoveryPrediction altP = new DiscoveryPrediction { Id = Id("prediction"), OutcomeId = outcomeId, Intercept = 0, Sigma = 1, Distribution = "GAUSSIAN", Rationale = "Minimum-relevant-effect response surface." }; altP.Terms[factorId] = 0.5; altH.Predictions.Add(altP); p.Hypotheses.Add(nullH); p.Hypotheses.Add(altH); p.Assumptions.Add("Prediction distributions and priors are operator-declared modeling inputs, not automatically calibrated probabilities."); return p;
        }

        private static DiscoveryProtocol ProjectStrategy(StrategyModel model)
        {
            DiscoveryProtocol p = new DiscoveryProtocol { Id = Id("protocol"), Name = "Discriminate SCM · " + (model.Name ?? "Strategy model"), Charter = "Experimental projection of a structural causal strategy model. Interventions become controllable factors; objectives become measured outcomes; equations remain hypotheses until empirically supported.", Status = "DRAFT", CreatedUtc = Now(), UpdatedUtc = Now(), DesignMethod = "D_OPTIMAL", RequestedRuns = 24, CandidatePool = 512, Replicates = 2, Seed = 1337, Budget = 1000000, RiskCeiling = 1000000 };
            foreach (StrategyVariable v in (model.Variables ?? new List<StrategyVariable>()).Where(v => Active(v.Status) && (Eq(v.Kind, "EXOGENOUS") || Eq(v.Kind, "DECISION"))).Take(MaxFactors)) p.Factors.Add(new DiscoveryFactor { Id = "strategy-" + v.Id, Name = v.Name, Kind = "CONTINUOUS", Unit = v.Unit, Status = "ACTIVE", Minimum = v.Minimum, Maximum = v.Maximum, Levels = 3, Controllable = Eq(v.Kind, "DECISION"), EvidenceNodeIds = new List<string>(v.EvidenceNodeIds ?? new List<string>()) });
            foreach (StrategyObjective o in (model.Objectives ?? new List<StrategyObjective>()).Where(o => Active(o.Status)).Take(MaxOutcomes)) { StrategyVariable v = model.Variables.FirstOrDefault(x => Eq(x.Id, o.VariableId)); p.Outcomes.Add(new DiscoveryOutcome { Id = "strategy-outcome-" + o.Id, Name = o.Name, Unit = v == null ? "index" : v.Unit, Scale = "CONTINUOUS", Direction = "TWO_SIDED", Status = "ACTIVE", NoiseSigma = 1, RelevantEffect = Math.Max(0.01, Math.Abs(o.Aspiration - (v == null ? 0 : v.Baseline)) * 0.25), Alpha = 0.05, TargetPower = 0.8, EvidenceNodeIds = v == null ? new List<string>() : new List<string>(v.EvidenceNodeIds ?? new List<string>()) }); }
            if (p.Factors.Count == 0) p.Factors.Add(new DiscoveryFactor { Id = Id("factor"), Name = "declared intervention intensity", Kind = "CONTINUOUS", Unit = "coded", Status = "ACTIVE", Minimum = -1, Maximum = 1, Levels = 3, Controllable = true }); if (p.Outcomes.Count == 0) p.Outcomes.Add(new DiscoveryOutcome { Id = Id("outcome"), Name = "declared strategic outcome", Unit = "index", Scale = "CONTINUOUS", Direction = "TWO_SIDED", Status = "ACTIVE", NoiseSigma = 1, RelevantEffect = 0.5, Alpha = 0.05, TargetPower = 0.8 });
            DiscoveryHypothesis h0 = new DiscoveryHypothesis { Id = Id("hypothesis"), Name = "H0 · baseline structural response", Family = "NULL", Status = "ACTIVE", Statement = "Observed response is not practically distinguishable from the declared baseline.", PriorWeight = 1, CreatedUtc = Now(), UpdatedUtc = Now() }; DiscoveryHypothesis h1 = new DiscoveryHypothesis { Id = Id("hypothesis"), Name = "H1 · projected SCM response", Family = "SCM_PROJECTION", Status = "ACTIVE", Statement = "Observed response follows the projected structural mechanism within declared noise.", PriorWeight = 1, CreatedUtc = Now(), UpdatedUtc = Now() };
            foreach (DiscoveryOutcome o in p.Outcomes) { DiscoveryPrediction n = new DiscoveryPrediction { Id = Id("prediction"), OutcomeId = o.Id, Intercept = 0, Sigma = Math.Max(0.0001, o.NoiseSigma), Distribution = "GAUSSIAN", Rationale = "No practically relevant response." }; DiscoveryPrediction a = new DiscoveryPrediction { Id = Id("prediction"), OutcomeId = o.Id, Intercept = 0, Sigma = Math.Max(0.0001, o.NoiseSigma), Distribution = "GAUSSIAN", Rationale = "Projected directional response requiring empirical calibration." }; foreach (DiscoveryFactor f in p.Factors) { n.Terms[f.Id] = 0; a.Terms[f.Id] = o.RelevantEffect / Math.Max(1, p.Factors.Count); } h0.Predictions.Add(n); h1.Predictions.Add(a); } p.Hypotheses.Add(h0); p.Hypotheses.Add(h1); p.Assumptions.Add("Projected from strategy model fingerprint " + Short(CounterfactualStrategyKernel.Fingerprint(model), 32) + "; structural coefficients are not automatically treated as empirical effect estimates."); p.EvidenceNodeIds.AddRange(model.EvidenceNodeIds ?? new List<string>()); return p;
        }

        private static void OpenProtocol(Window owner, DeepSystemsContext ctx, WorldIndex index, DiscoveryProtocol p)
        {
            Window w = W(owner, "YOMI · DISCOVERY PROTOCOL · " + p.Name, 1300, 860); DockPanel root = Shell((p.Status ?? "DRAFT") + " · " + p.Name, (p.DesignMethod ?? "D_OPTIMAL") + " · " + p.RequestedRuns + " requested runs / " + p.Replicates + " replicates · r" + p.Revision + " · fingerprint " + Short(ExperimentalDesignKernel.ProtocolFingerprint(p), 20)); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("ADD FACTOR", delegate { AddFactor(w, ctx, p); })); tools.Children.Add(Btn("ADD OUTCOME", delegate { AddOutcome(w, ctx, p); })); tools.Children.Add(Btn("ADD HYPOTHESIS", delegate { AddHypothesis(w, ctx, p); })); tools.Children.Add(Btn("ADD PREDICTION", delegate { AddPrediction(w, ctx, p); })); tools.Children.Add(Btn("DESIGN SETTINGS", delegate { EditDesign(w, ctx, p); })); tools.Children.Add(Btn("PREREG FIELDS", delegate { EditPreregistrationFields(w, ctx, p); })); tools.Children.Add(Btn("FREEZE PREREG", delegate { FreezePreregistration(w, ctx, p); })); tools.Children.Add(Btn("SYNTHESIZE DESIGN", delegate { GenerateDesign(w, ctx, index, p); })); tools.Children.Add(Btn("POWER", delegate { OpenPower(w, p); })); tools.Children.Add(Btn("CYBERNETIC TWIN", delegate { CyberneticDigitalTwinMetastructure.OpenFromDiscoveryProtocol(w, ctx, index, p); })); tools.Children.Add(Btn("COMPLEX POPULATION", delegate { ComplexSystemsLaboratory.OpenFromDiscoveryProtocol(w, ctx, index, p); })); tools.Children.Add(Btn("OPTIMIZE EXPERIMENTS", delegate { OperationsResearchEmpire.OpenFromDiscoveryProtocol(w, ctx, index, p); })); tools.Children.Add(Btn("AUDIT", delegate { OpenProtocolAudit(w, p); })); tools.Children.Add(Btn(Active(p.Status) ? "ARCHIVE" : "RESTORE", delegate { p.Status = Active(p.Status) ? "ARCHIVED" : "ACTIVE"; Touch(p); Save(ctx); AppendLedger(ctx, "PROTOCOL_" + p.Status, p.Id, p.Name, ExperimentalDesignKernel.ProtocolFingerprint(p), ""); w.Close(); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, p.Name, p, StorePath(ctx), "$protocols:" + p.Id, "DISCOVERY › PROTOCOL"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools);
            Grid body = new Grid(); body.ColumnDefinitions.Add(new ColumnDefinition()); body.ColumnDefinitions.Add(new ColumnDefinition()); body.ColumnDefinitions.Add(new ColumnDefinition()); ListBox factors = List(); factors.ItemsSource = p.Factors; factors.MouseDoubleClick += delegate { DiscoveryFactor f = factors.SelectedItem as DiscoveryFactor; if (f != null) OpenFactor(w, ctx, index, p, f); }; ListBox outcomes = List(); outcomes.ItemsSource = p.Outcomes; outcomes.MouseDoubleClick += delegate { DiscoveryOutcome o = outcomes.SelectedItem as DiscoveryOutcome; if (o != null) OpenOutcome(w, ctx, index, p, o); }; ListBox hypotheses = List(); hypotheses.ItemsSource = p.Hypotheses; hypotheses.MouseDoubleClick += delegate { DiscoveryHypothesis h = hypotheses.SelectedItem as DiscoveryHypothesis; if (h != null) OpenHypothesis(w, ctx, index, p, h); }; Grid.SetColumn(factors, 0); Grid.SetColumn(outcomes, 1); Grid.SetColumn(hypotheses, 2); body.Children.Add(factors); body.Children.Add(outcomes); body.Children.Add(hypotheses); root.Children.Add(body); w.Content = root; w.Show();
        }

        private static void AddFactor(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p) { if (p.Factors.Count >= MaxFactors) return; string name = Prompt(owner, "ADD FACTOR", "Factor name", "experimental factor"); if (String.IsNullOrWhiteSpace(name)) return; string kind = Choose(owner, "FACTOR KIND", "Measurement scale", new[] { "CONTINUOUS", "ORDINAL", "CATEGORICAL", "BINARY" }, "CONTINUOUS"); if (kind == null) return; double min = Number(Prompt(owner, "LOW LEVEL", "Minimum coded or physical level", "-1"), -1), max = Number(Prompt(owner, "HIGH LEVEL", "Maximum coded or physical level", "1"), 1); if (max < min) { double t = min; min = max; max = t; } int levels = (int)Math.Max(2, Math.Min(32, Number(Prompt(owner, "LEVELS", "Discrete levels for factorial designs", "2"), 2))); string control = Choose(owner, "ASSIGNMENT", "Can the operator randomize this factor?", new[] { "CONTROLLABLE", "OBSERVATIONAL" }, "CONTROLLABLE"); if (control == null) return; double cost = Math.Max(0, Number(Prompt(owner, "PER-RUN COST", "Nonnegative cost burden", "0"), 0)), risk = Math.Max(0, Number(Prompt(owner, "PER-RUN RISK", "Nonnegative risk burden", "0"), 0)); p.Factors.Add(new DiscoveryFactor { Id = Id("factor"), Name = Short(name, 240), Kind = kind, Unit = Short(Prompt(owner, "UNIT", "Physical or coded unit", "coded"), 80), Status = "ACTIVE", Minimum = min, Maximum = max, Levels = levels, Controllable = control == "CONTROLLABLE", PerRunCost = cost, PerRunRisk = risk }); Touch(p); Save(ctx); AppendLedger(ctx, "FACTOR_ADDED", p.Id, name, ExperimentalDesignKernel.ProtocolFingerprint(p), ""); }
        private static void AddOutcome(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p) { if (p.Outcomes.Count >= MaxOutcomes) return; string name = Prompt(owner, "ADD OUTCOME", "Measured outcome", "primary outcome"); if (String.IsNullOrWhiteSpace(name)) return; string scale = Choose(owner, "OUTCOME SCALE", "Declared measurement family", new[] { "CONTINUOUS", "BINARY", "COUNT", "ORDINAL" }, "CONTINUOUS"); if (scale == null) return; double sigma = Math.Max(0.0000001, Number(Prompt(owner, "NOISE SIGMA", "Declared measurement / outcome standard deviation", "1"), 1)), effect = Math.Max(0.0000001, Math.Abs(Number(Prompt(owner, "MINIMUM RELEVANT EFFECT", "Smallest effect worth detecting", "0.5"), 0.5))), alpha = Math.Max(0.0000001, Math.Min(0.5, Number(Prompt(owner, "ALPHA", "Type-I error boundary", "0.05"), 0.05))), power = Math.Max(0.500001, Math.Min(0.999999, Number(Prompt(owner, "TARGET POWER", "1−β", "0.8"), 0.8))); p.Outcomes.Add(new DiscoveryOutcome { Id = Id("outcome"), Name = Short(name, 240), Unit = Short(Prompt(owner, "UNIT", "Measurement unit", "index"), 80), Scale = scale, Direction = "TWO_SIDED", Status = "ACTIVE", NoiseSigma = sigma, RelevantEffect = effect, Alpha = alpha, TargetPower = power }); Touch(p); Save(ctx); AppendLedger(ctx, "OUTCOME_ADDED", p.Id, name, ExperimentalDesignKernel.ProtocolFingerprint(p), ""); }
        private static void AddHypothesis(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p) { if (p.Hypotheses.Count >= MaxHypotheses) return; string name = Prompt(owner, "ADD HYPOTHESIS", "Hypothesis name", "Competing mechanism"); if (String.IsNullOrWhiteSpace(name)) return; string statement = PromptLarge(owner, "HYPOTHESIS STATEMENT", "Falsifiable empirical statement and boundary", "The declared response surface differs from every retained competitor."); if (statement == null) return; double prior = Math.Max(0, Number(Prompt(owner, "PRIOR WEIGHT", "Relative plausibility weight; need not sum to one", "1"), 1)); p.Hypotheses.Add(new DiscoveryHypothesis { Id = Id("hypothesis"), Name = Short(name, 240), Family = "COMPETING_MODEL", Status = "ACTIVE", Statement = Short(statement, MaxLongText), PriorWeight = prior, CreatedUtc = Now(), UpdatedUtc = Now() }); Touch(p); Save(ctx); AppendLedger(ctx, "HYPOTHESIS_ADDED", p.Id, name, ExperimentalDesignKernel.ProtocolFingerprint(p), ""); }
        private static void AddPrediction(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p) { DiscoveryHypothesis h = ChooseObject(owner, "SELECT HYPOTHESIS", "Prediction owner", p.Hypotheses.Cast<object>().ToList()) as DiscoveryHypothesis; if (h == null || h.Predictions.Count >= MaxPredictions) return; DiscoveryOutcome o = ChooseObject(owner, "SELECT OUTCOME", "Predicted response", p.Outcomes.Cast<object>().ToList()) as DiscoveryOutcome; if (o == null) return; double intercept = Number(Prompt(owner, "PREDICTED INTERCEPT", "Mean at zero-coded factor levels", "0"), 0), sigma = Math.Max(0.0000001, Number(Prompt(owner, "PREDICTIVE SIGMA", "Declared Gaussian predictive standard deviation", o.NoiseSigma.ToString("R", CultureInfo.InvariantCulture)), o.NoiseSigma)); DiscoveryPrediction q = new DiscoveryPrediction { Id = Id("prediction"), OutcomeId = o.Id, Intercept = intercept, Sigma = sigma, Distribution = "GAUSSIAN", Rationale = Short(PromptLarge(owner, "PREDICTION RATIONALE", "Mechanistic rationale and caveats", "Operator-declared response surface."), MaxLongText) }; foreach (DiscoveryFactor f in p.Factors.Where(x => Active(x.Status)).Take(MaxTerms)) q.Terms[f.Id] = Number(Prompt(owner, "TERM · " + f.Name, "Coefficient for raw factor value; zero retains no main effect", "0"), 0); h.Predictions.Add(q); h.UpdatedUtc = Now(); Touch(p); Save(ctx); AppendLedger(ctx, "PREDICTION_ADDED", h.Id, o.Name, ExperimentalDesignKernel.ProtocolFingerprint(p), ""); }

        private static void EditDesign(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p) { string method = Choose(owner, "DESIGN METHOD", "Candidate synthesis strategy", new[] { "D_OPTIMAL", "LATIN_HYPERCUBE", "HALTON", "FULL_FACTORIAL", "FRACTIONAL_FACTORIAL" }, p.DesignMethod); if (method == null) return; p.DesignMethod = method; p.RequestedRuns = (int)Math.Max(1, Math.Min(4096, Number(Prompt(owner, "RUNS", "Requested base design runs", p.RequestedRuns.ToString(CultureInfo.InvariantCulture)), p.RequestedRuns))); p.Replicates = (int)Math.Max(1, Math.Min(64, Number(Prompt(owner, "REPLICATES", "Planned complete replicates", p.Replicates.ToString(CultureInfo.InvariantCulture)), p.Replicates))); p.CandidatePool = (int)Math.Max(p.RequestedRuns, Math.Min(8192, Number(Prompt(owner, "CANDIDATE POOL", "Candidate points considered by D-optimal exchange", p.CandidatePool.ToString(CultureInfo.InvariantCulture)), p.CandidatePool))); p.Seed = (int)Number(Prompt(owner, "DESIGN SEED", "Deterministic sequence seed", p.Seed.ToString(CultureInfo.InvariantCulture)), p.Seed); p.Budget = Math.Max(0, Number(Prompt(owner, "BUDGET", "Maximum aggregate design cost", p.Budget.ToString("R", CultureInfo.InvariantCulture)), p.Budget)); p.RiskCeiling = Math.Max(0, Number(Prompt(owner, "RISK CEILING", "Maximum aggregate risk", p.RiskCeiling.ToString("R", CultureInfo.InvariantCulture)), p.RiskCeiling)); Touch(p); Save(ctx); AppendLedger(ctx, "DESIGN_SETTINGS_REVISED", p.Id, method, ExperimentalDesignKernel.ProtocolFingerprint(p), ""); }
        private static void EditPreregistrationFields(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p) { string stopping = PromptLarge(owner, "STOPPING RULE", "Fixed or sequential stopping rule; specify decision boundary", p.StoppingRule); if (stopping == null) return; string analysis = PromptLarge(owner, "ANALYSIS PLAN", "Primary model, contrasts, multiplicity and reporting", p.AnalysisPlan); if (analysis == null) return; string exclusions = PromptLarge(owner, "EXCLUSION RULE", "Pre-outcome exclusion and missingness rules", p.ExclusionRule); if (exclusions == null) return; string randomization = PromptLarge(owner, "RANDOMIZATION RULE", "Assignment and sequence-generation rule", p.RandomizationRule); if (randomization == null) return; string blocking = PromptLarge(owner, "BLOCKING RULE", "Blocks, strata and batch boundaries", p.BlockingRule); if (blocking == null) return; p.StoppingRule = Short(stopping, MaxLongText); p.AnalysisPlan = Short(analysis, MaxLongText); p.ExclusionRule = Short(exclusions, MaxLongText); p.RandomizationRule = Short(randomization, MaxLongText); p.BlockingRule = Short(blocking, MaxLongText); Touch(p); Save(ctx); AppendLedger(ctx, "PREREG_FIELDS_REVISED", p.Id, "stopping · analysis · exclusion · randomization · blocking", ExperimentalDesignKernel.ProtocolFingerprint(p), ""); }
        private static void FreezePreregistration(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p) { List<string> audit = ExperimentalDesignKernel.Audit(p); if (audit.Any(x => x.StartsWith("BLOCKER", StringComparison.OrdinalIgnoreCase))) { MessageBox.Show(owner, String.Join("\r\n", audit.ToArray()), "YOMI · Preregistration Blocked"); return; } string protocolHash = ExperimentalDesignKernel.ProtocolFingerprint(p), preregHash = ExperimentalDesignKernel.PreregistrationFingerprint(p); DiscoveryPreregistration latest = Store.Preregistrations.Where(x => Eq(x.ProtocolId, p.Id)).OrderByDescending(x => x.FrozenUtc).FirstOrDefault(); if (latest != null && Eq(latest.PreregistrationFingerprint, preregHash)) { MessageBox.Show(owner, "An identical frozen preregistration already exists.\r\n\r\n" + preregHash, "YOMI · Preregistration Vault"); return; } string reason = latest == null ? "INITIAL FREEZE" : PromptLarge(owner, "PREREGISTRATION AMENDMENT", "Explain why the frozen boundary changed; prior freeze remains immutable", "Protocol amendment before additional observation intake."); if (reason == null) return; DiscoveryPreregistration frozen = new DiscoveryPreregistration { Id = Id("preregistration"), ProtocolId = p.Id, FrozenUtc = Now(), Status = latest == null ? "FROZEN" : "AMENDED", ParentPreregistrationId = latest == null ? "" : latest.Id, AmendmentReason = Short(reason, MaxLongText), ProtocolFingerprint = protocolHash, PreregistrationFingerprint = preregHash, SnapshotJson = Json.Serialize(p) }; Store.Preregistrations.Insert(0, frozen); Save(ctx); AppendLedger(ctx, latest == null ? "PREREGISTRATION_FROZEN" : "PREREGISTRATION_AMENDED", p.Id, reason, protocolHash, preregHash); MessageBox.Show(owner, "Frozen boundary created.\r\n\r\n" + preregHash, "YOMI · Preregistration Vault"); }

        private static void GenerateDesign(Window owner, DeepSystemsContext ctx, WorldIndex index, DiscoveryProtocol p) { List<string> audit = ExperimentalDesignKernel.Audit(p); if (audit.Any(x => x.StartsWith("BLOCKER", StringComparison.OrdinalIgnoreCase))) { MessageBox.Show(owner, String.Join("\r\n", audit.ToArray()), "YOMI · Design Blocked"); return; } List<DiscoveryRun> runs = ExperimentalDesignKernel.Generate(p); DiscoveryDesignDiagnostics diagnostics = ExperimentalDesignKernel.Diagnose(p, runs); DiscoveryDiscrimination discrimination = ExperimentalDesignKernel.Discriminate(p, runs); string protocolHash = ExperimentalDesignKernel.ProtocolFingerprint(p), prereg = ExperimentalDesignKernel.PreregistrationFingerprint(p), designHash = HashText(protocolHash + "|" + String.Join("|", runs.Select(RunFingerprint).ToArray())); DiscoveryDesignRecord record = new DiscoveryDesignRecord { Id = Id("design"), ProtocolId = p.Id, CreatedUtc = Now(), ProtocolFingerprint = protocolHash, PreregistrationFingerprint = prereg, DesignFingerprint = designHash, Method = p.DesignMethod, Runs = runs, Diagnostics = diagnostics, Discrimination = discrimination, PowerPlans = ExperimentalDesignKernel.PowerPlans(p) }; record.CertificateHash = HashText("DISCOVERY_DESIGN_CERTIFICATE_V1|" + record.Id + "|" + protocolHash + "|" + prereg + "|" + designHash + "|" + diagnostics.Rank + "|" + diagnostics.LogDeterminant.ToString("R", CultureInfo.InvariantCulture) + "|" + discrimination.ExpectedInformationGainBits.ToString("R", CultureInfo.InvariantCulture)); Store.Designs.Insert(0, record); TrimStore(); Save(ctx); AppendLedger(ctx, "DESIGN_SYNTHESIZED", record.Id, runs.Count + " runs · " + diagnostics.Rank + "/" + diagnostics.Parameters + " rank", protocolHash, record.CertificateHash); OpenDesign(owner, ctx, index, record); }
        private static void OpenDesigns(Window owner, DeepSystemsContext ctx, WorldIndex index) { Window w = W(owner, "YOMI · FROZEN DESIGN VAULT", 1180, 760); DockPanel root = Shell("FROZEN DESIGN VAULT", Store.Designs.Count + " immutable design records; each retains source protocol and preregistration fingerprints."); ListBox list = List(); list.ItemsSource = Store.Designs.OrderByDescending(x => x.CreatedUtc).ToList(); list.MouseDoubleClick += delegate { DiscoveryDesignRecord d = list.SelectedItem as DiscoveryDesignRecord; if (d != null) OpenDesign(w, ctx, index, d); }; root.Children.Add(list); w.Content = root; w.Show(); }
        private static void OpenDesign(Window owner, DeepSystemsContext ctx, WorldIndex index, DiscoveryDesignRecord d) { DiscoveryProtocol p = Protocol(d.ProtocolId); bool drift = p == null || !Eq(ExperimentalDesignKernel.ProtocolFingerprint(p), d.ProtocolFingerprint); Window w = W(owner, "YOMI · EXPERIMENT DESIGN · " + d.Method, 1320, 860); DockPanel root = Shell((drift ? "PROTOCOL DRIFT · HISTORICAL DESIGN" : "PROTOCOL CURRENT") + " · " + d.Method, (d.Diagnostics == null ? "UNDIAGNOSED" : d.Diagnostics.ToString()) + "\r\n" + (d.Discrimination == null ? "" : d.Discrimination.ToString()) + "\r\ncertificate " + d.CertificateHash); WrapPanel tools = new WrapPanel(); tools.Children.Add(Btn("OBSERVATION INTAKE", delegate { if (p != null) RecordObservation(w, ctx, p, d); })); tools.Children.Add(Btn("POSTERIOR", delegate { if (p != null) OpenPosteriorForDesign(w, ctx, p, d); })); tools.Children.Add(Btn("REPRODUCIBILITY", delegate { if (p != null) OpenReproducibilityForDesign(w, ctx, p, d); })); tools.Children.Add(Btn("CREATE DOSSIER", delegate { if (p != null) CreateDossier(w, ctx, index, p, d); })); tools.Children.Add(Btn("ALIASES", delegate { if (d.Diagnostics != null) OpenRows(w, "DESIGN ALIAS CARTOGRAPHY", d.Diagnostics.Aliases.Cast<object>().ToList(), "Pairwise centered term correlations; exact aliases imply non-identifiability."); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, "Design " + d.Id, d, StorePath(ctx), "$designs:" + d.Id, "DISCOVERY › DESIGN"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox runs = List(); runs.ItemsSource = d.Runs; DockPanel.SetDock(runs, Dock.Top); runs.MaxHeight = 430; root.Children.Add(runs); string audit = "WARNINGS\r\n" + String.Join("\r\n", (d.Diagnostics == null ? new List<string>() : d.Diagnostics.Warnings).Select(x => "  ! " + x).ToArray()) + "\r\n\r\nDISCRIMINATION AUDIT\r\n" + String.Join("\r\n", (d.Discrimination == null ? new List<string>() : d.Discrimination.Audit).Select(x => "  • " + x).ToArray()); root.Children.Add(ReadOnly(audit)); w.Content = root; w.Show(); }

        private static void RecordObservation(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p, DiscoveryDesignRecord d) { DiscoveryRun run = ChooseObject(owner, "SELECT RUN", "Manual observation provenance anchor", d.Runs.Cast<object>().ToList()) as DiscoveryRun; if (run == null) return; DiscoveryOutcome outcome = ChooseObject(owner, "SELECT OUTCOME", "Measured response", p.Outcomes.Cast<object>().ToList()) as DiscoveryOutcome; if (outcome == null) return; string raw = Prompt(owner, "OBSERVED VALUE", "Manually recorded value; this surface does not execute or acquire measurements", "0"); if (raw == null) return; double value = Number(raw, Double.NaN); if (Double.IsNaN(value)) return; double se = Math.Max(0, Number(Prompt(owner, "STANDARD ERROR", "Declared standard error; zero means unreported", "0"), 0)); string provenance = PromptLarge(owner, "OBSERVATION PROVENANCE", "Source, instrument, operator, timestamp and integrity notes", "Manual intake. No experiment was executed by YOMI."); if (provenance == null) return; DiscoveryObservation o = new DiscoveryObservation { Id = Id("observation"), RunId = run.Id, OutcomeId = outcome.Id, Value = value, StandardError = se, Status = "OBSERVED", RecordedUtc = Now(), Provenance = Short(provenance, MaxLongText) }; Store.Observations.Insert(0, o); TrimStore(); Save(ctx); AppendLedger(ctx, "OBSERVATION_RECORDED", o.Id, run.Id + " · " + outcome.Id + " · " + value.ToString("R", CultureInfo.InvariantCulture), d.ProtocolFingerprint, d.CertificateHash); }
        private static void OpenPosterior(Window owner, DeepSystemsContext ctx, WorldIndex index, DiscoveryProtocol p) { DiscoveryDesignRecord d = Store.Designs.Where(x => Eq(x.ProtocolId, p.Id)).OrderByDescending(x => x.CreatedUtc).FirstOrDefault(); if (d == null) { MessageBox.Show(owner, "Synthesize a design before updating hypotheses.", "YOMI · Sequential Inference"); return; } OpenPosteriorForDesign(owner, ctx, p, d); }
        private static void OpenPosteriorForDesign(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p, DiscoveryDesignRecord d) { List<DiscoveryObservation> observations = Store.Observations.Where(o => d.Runs.Any(r => Eq(r.Id, o.RunId)) && p.Outcomes.Any(x => Eq(x.Id, o.OutcomeId))).ToList(); List<DiscoveryHypothesisPosterior> rows = ExperimentalDesignKernel.Update(p, d.Runs, observations); OpenRows(owner, "SEQUENTIAL HYPOTHESIS POSTERIOR", rows.Cast<object>().ToList(), observations.Count + " recorded observations · priors are normalized weights · likelihoods use declared Gaussian response surfaces and standard errors."); }
        private static void OpenPower(Window owner, DiscoveryProtocol p) { OpenRows(owner, "POWER & SAMPLE-SIZE PLANS", ExperimentalDesignKernel.PowerPlans(p).Cast<object>().ToList(), "Explicit z-approximation assumptions are retained on every row; these are planning numbers, not guarantees."); }
        private static void OpenReproducibility(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p) { DiscoveryDesignRecord d = Store.Designs.Where(x => Eq(x.ProtocolId, p.Id)).OrderByDescending(x => x.CreatedUtc).FirstOrDefault(); if (d == null) return; OpenReproducibilityForDesign(owner, ctx, p, d); }
        private static void OpenReproducibilityForDesign(Window owner, DeepSystemsContext ctx, DiscoveryProtocol p, DiscoveryDesignRecord d) { List<DiscoveryObservation> observations = Store.Observations.Where(o => d.Runs.Any(r => Eq(r.Id, o.RunId))).ToList(); DiscoveryReproducibilityProfile profile = ExperimentalDesignKernel.Reproducibility(p, d.Runs, observations); OpenRows(owner, "REPLICATION OBSERVATORY", new List<object> { profile }.Concat(profile.Warnings.Cast<object>()).ToList(), observations.Count + " observations in the selected immutable design boundary."); }

