        private static void OpenPreregistration(Window owner, DeepSystemsContext ctx, DiscoveryPreregistration p) { Window w = W(owner, "YOMI · PREREGISTRATION · " + p.Id, 1120, 780); DockPanel root = Shell((p.Status ?? "FROZEN") + " · " + p.FrozenUtc, "protocol " + p.ProtocolFingerprint + "\r\npreregistration " + p.PreregistrationFingerprint + (String.IsNullOrWhiteSpace(p.ParentPreregistrationId) ? "" : "\r\nparent " + p.ParentPreregistrationId)); root.Children.Add(ReadOnly("AMENDMENT REASON\r\n" + p.AmendmentReason + "\r\n\r\nFROZEN JSON SNAPSHOT\r\n" + p.SnapshotJson)); w.Content = root; w.Show(); }
