        private static void OpenDossier(Window owner, DeepSystemsContext ctx, WorldIndex index, DiscoveryDossier d) { DiscoveryProtocol p = Protocol(d.ProtocolId); bool drift = p == null || !Eq(ExperimentalDesignKernel.ProtocolFingerprint(p), d.ProtocolFingerprint); Window w = W(owner, "YOMI · DISCOVERY DOSSIER · " + d.Title, 1220, 820); DockPanel root = Shell((d.Status ?? "DRAFT") + " · " + d.Title, (drift ? "PROTOCOL DRIFT · HISTORICAL BOUNDARY RETAINED" : "PROTOCOL FINGERPRINT CURRENT") + "\r\ncertificate " + d.DesignCertificate); WrapPanel tools = new WrapPanel(); foreach (string status in new[] { "DRAFT", "REVIEWING", "REGISTERED", "RETIRED" }) { string captured = status; tools.Children.Add(Btn(captured, delegate { d.Status = captured; d.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "DOSSIER_" + captured, d.Id, d.Title, d.ProtocolFingerprint, d.DesignCertificate); })); } tools.Children.Add(Btn("ADD CAVEAT", delegate { string text = PromptLarge(w, "DOSSIER CAVEAT", "Threat to validity, alternative explanation or boundary", ""); if (!String.IsNullOrWhiteSpace(text)) { d.Caveats.Insert(0, Short(text, MaxLongText)); d.Caveats = d.Caveats.Take(512).ToList(); d.UpdatedUtc = Now(); Save(ctx); } })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, d.Title, d, StorePath(ctx), "$dossiers:" + d.Id, "DISCOVERY › DOSSIER"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); root.Children.Add(ReadOnly("QUESTION\r\n" + d.Question + "\r\n\r\nDESIGN BOUNDARY\r\n" + d.DesignBoundary + "\r\n\r\nINTERPRETATION BOUNDARY\r\n" + d.InterpretationBoundary + "\r\n\r\nCAVEATS\r\n" + String.Join("\r\n", d.Caveats.Select(x => "  ! " + x).ToArray()))); root.Children.Add(EvidenceList(w, ctx, index, d.EvidenceNodeIds)); w.Content = root; w.Show(); }

