        private static void AddPortfolioCandidate(Window owner, DeepSystemsContext ctx) { string name = Prompt(owner, "EXPERIMENT CANDIDATE", "Candidate name", "Candidate experiment"); if (String.IsNullOrWhiteSpace(name)) return; double value = Math.Max(0, Number(Prompt(owner, "INFORMATION VALUE", "Declared expected information gain or comparable score", "1"), 1)), cost = Math.Max(0, Number(Prompt(owner, "COST", "Aggregate monetary/time burden", "1"), 1)), risk = Math.Max(0, Number(Prompt(owner, "RISK", "Aggregate ethical/operational risk", "0"), 0)); string mandatory = Choose(owner, "MANDATORY", "Must this candidate be included?", new[] { "NO", "YES" }, "NO"); DiscoveryExperimentCandidate c = new DiscoveryExperimentCandidate { Id = Id("experiment"), Name = Short(name, 240), InformationValue = value, Cost = cost, Risk = risk, Mandatory = mandatory == "YES" }; c.RequiresIds = Lines(PromptLarge(owner, "DEPENDENCIES", "Required candidate IDs, one per line", "")).Take(64).ToList(); c.ExcludesIds = Lines(PromptLarge(owner, "EXCLUSIONS", "Mutually exclusive candidate IDs, one per line", "")).Take(64).ToList(); Store.PortfolioCandidates.Insert(0, c); Save(ctx); AppendLedger(ctx, "PORTFOLIO_CANDIDATE_ADDED", c.Id, c.Name, "", ""); }
