        private static void OpenFactor(Window owner, DeepSystemsContext ctx, WorldIndex index, DiscoveryProtocol p, DiscoveryFactor f) { Window w = W(owner, "YOMI · FACTOR · " + f.Name, 1060, 720); DockPanel root = Shell((f.Controllable ? "CONTROLLABLE" : "OBSERVATIONAL") + " · " + f.Name, "Domain [" + f.Minimum.ToString("0.######", CultureInfo.InvariantCulture) + ", " + f.Maximum.ToString("0.######", CultureInfo.InvariantCulture) + "] · " + f.Levels + " levels · cost " + f.PerRunCost + " · risk " + f.PerRunRisk); WrapPanel tools = new WrapPanel(); tools.Children.Add(Btn(f.Controllable ? "MARK OBSERVATIONAL" : "MARK CONTROLLABLE", delegate { f.Controllable = !f.Controllable; Touch(p); Save(ctx); w.Close(); })); tools.Children.Add(Btn(Active(f.Status) ? "DISABLE" : "ENABLE", delegate { f.Status = Active(f.Status) ? "DISABLED" : "ACTIVE"; Touch(p); Save(ctx); w.Close(); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); root.Children.Add(EvidenceList(w, ctx, index, f.EvidenceNodeIds)); w.Content = root; w.Show(); }
